// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract Recorder {
    uint256 public calls;
    address public lastFrom;
    address public lastTo;
    uint256 public lastAmount;

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        calls++;
        lastFrom = from;
        lastTo = to;
        lastAmount = amount;
        return true;
    }
}

contract InvMutTest is Test {
    airPort c;
    Recorder rec;

    function setUp() public {
        c = new airPort();
        rec = new Recorder();
    }

    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        // keep the domain wide: non-empty recipient list only
        vm.assume(tos.length > 0);

        bool ok;
        try c.transfer(from, address(rec), tos, v) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        // Reference: completes and the recording callee saw exactly one call per recipient.
        // Mutant: reverts due to the out-of-bounds access, so ok is false and the equality fails.
        assertTrue(ok && rec.calls() == tos.length);
    }
}
